#!/usr/bin/env node
/**
 * Source-level bans that previously lived only in AGENTS.md prose. Prose
 * guards nothing when code is generated by an LLM that pattern-matches from
 * its training data rather than this repo's rules — these are the two rules
 * most likely to be violated by plausible-looking generated code:
 *
 *   1. localStorage/sessionStorage are banned repo-wide (AGENTS rule 5).
 *      The consent decision is a cookie; attribution is honestly last-touch
 *      BECAUSE first-touch would need storage. "Just cache it in
 *      localStorage" is the single most statistically likely improvement a
 *      generated snippet will try to make.
 *   2. No colour literals outside the token files (AGENTS rule 6). Every
 *      token is measured against WCAG AA by the contrast sweep — a hex
 *      literal in a component is a colour the sweep can measure but nobody
 *      chose, and the ancestor site's hand-picked brand colour measured
 *      2.8:1. Allowed: src/styles/global.css (the tokens) and
 *      src/data/site.ts (themeColor, a browser-chrome hint that renders no
 *      text). marketing/ is out of scope (BRAND_BG literals are documented
 *      per-site knobs).
 *
 * Plus the content-level rules that grow back silently as pages are added:
 * the author registry, blog cadence and in-body interlinks, claims the site
 * may not make (voice.json → site.bannedClaims), and frontmatter titles the
 * SERP clamp would hard-cut. Each carries its WHY inline.
 *
 * Fast (pure grep over src/ + worker/), so it runs in the pre-commit hook.
 */

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

let fail = 0;
const bad = (msg) => {
  console.log(`   FAIL: ${msg}`);
  fail = 1;
};

function walk(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(astro|ts|mjs|js|css)$/.test(name)) out.push(p);
  }
  return out;
}

const files = [...walk('src'), ...walk('worker')];

console.log('→ no localStorage/sessionStorage anywhere (AGENTS rule 5)');
let found = 0;
for (const f of files) {
  const text = readFileSync(f, 'utf8');
  // Property access or indexing only — prose mentions in comments are fine.
  for (const m of text.matchAll(/(?:window\.)?(localStorage|sessionStorage)\s*[.[]/g)) {
    const line = text.slice(0, m.index).split('\n').length;
    bad(`${f}:${line} uses ${m[1]} — banned repo-wide; use a cookie or don't store it`);
    found = 1;
  }
}
if (!found) console.log('   ok');

console.log('→ no colour literals outside the token files (AGENTS rule 6)');
const HEX_ALLOWED = new Set(['src/styles/global.css', 'src/data/site.ts']);
found = 0;
for (const f of files) {
  if (HEX_ALLOWED.has(f.split('\\').join('/'))) continue;
  const text = readFileSync(f, 'utf8');
  for (const m of text.matchAll(/#[0-9a-fA-F]{3,8}\b(?=[^\w-]|$)/gm)) {
    // Ignore obvious non-colour hits: URL fragments and hex in ids.
    const before = text.slice(Math.max(0, m.index - 20), m.index);
    if (/(href="|url\(|&|id=)$/.test(before)) continue;
    const line = text.slice(0, m.index).split('\n').length;
    bad(`${f}:${line} has colour literal ${m[0]} — use a token from global.css (colour is measured, not eyeballed)`);
    found = 1;
  }
}
if (!found) console.log('   ok');

console.log('→ every blog author is in the registry (src/data/authors.json → /author/<slug>)');
// A byline that links nowhere is a name, not a credential. The blog template
// links each byline to its author page by matching the registry; a post whose
// author is missing from the registry would silently render an unlinked name.
const REG = JSON.parse(readFileSync('src/data/authors.json', 'utf8')).authors;
found = 0;
for (const f of readdirSync('src/content/blog').filter((n) => /\.mdx?$/.test(n))) {
  const p = join('src/content/blog', f);
  const text = readFileSync(p, 'utf8');
  if (/^draft:\s*true$/m.test(text)) continue;
  const name = text.match(/^author:\s*\n\s+name:\s*['"]?([^'"\n]+?)['"]?\s*$/m)?.[1];
  const sameAs = [...text.matchAll(/^\s+-\s+['"]?(https?:\/\/[^'"\s]+)['"]?\s*$/gm)].map((m) => m[1]);
  const hit = REG.find((a) => a.sameAs.some((s) => sameAs.includes(s)) || a.name === name);
  if (!hit) {
    bad(`${p} author "${name ?? '(unparsed)'}" matches no entry in src/data/authors.json — add the author (real profile, real bio) so the byline links to /author/<slug>`);
    found = 1;
  }
}
if (!found) console.log('   ok');

console.log('→ blog dates parse and in-body interlinks (AGENTS § Content rules)');
// Inherited from the ancestor site's first month of Search Console data: its
// first six posts shipped all dated the same day and with zero in-body links.
// Both were fixed by hand and both are the kind of defect that regrows
// silently as posts are added. Dates: parseable (no per-date or per-week cap since 20 Sep 2026).
// Links: at least 2 contextual in-body internal links per post — a
// generated related-posts footer does not count, which is why this reads the
// markdown body, not the built page.
found = 0;
for (const f of readdirSync('src/content/blog').filter((n) => /\.mdx?$/.test(n))) {
  const p = join('src/content/blog', f);
  const text = readFileSync(p, 'utf8');
  if (/^draft:\s*true$/m.test(text)) continue;
  const date = text.match(/^published:\s*['"]?(\d{4}-\d{2}-\d{2})['"]?\s*$/m)?.[1];
  if (!date) {
    bad(`${p} has no parseable "published: YYYY-MM-DD" line`);
    found = 1;
    continue;
  }
  const body = text.replace(/^---\n[\s\S]*?\n---\n/, '');
  const links = [...body.matchAll(/\]\(\/[a-z]/g)].length;
  if (links < 2) {
    bad(`${p} has ${links} in-body internal link(s) — minimum 2, anchored on the phrase a searcher types (AGENTS § Content rules)`);
    found = 1;
  }
}
if (!found) console.log('   ok');

console.log('→ no banned claims in content (voice.json → site.bannedClaims: a model is not a measurement)');
// Assertions of fact the site may not make — a measurement nobody took, a
// customer that does not exist, a result the product has not produced. The
// ancestor site claimed a design partner it never had; 106 places across 33
// files were built on it, the rewrite removed the wording, and the claim
// regrew nine times in the following month in shapes the prose rule did not
// name ("we measured" became "we timed"). Prose guards nothing here; a regex
// per CLAIM does. The patterns are the site's own (voice.json site layer,
// filled by /onboard-marketing from STRATEGY.md § Honest state) — this script
// is only the mechanism, and an empty list is a pass. Scope is everything
// that renders: content, pages, layouts, components, and facts.json (whose
// `source` strings do not render but do get quoted).
function walkContent(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walkContent(p, out);
    else if (/\.(mdx?|astro|ts|json)$/.test(name)) out.push(p);
  }
  return out;
}
const VOICE_SITE = JSON.parse(readFileSync('src/data/voice.json', 'utf8')).site ?? {};
const CLAIM_PATTERNS = (VOICE_SITE.bannedClaims ?? []).map((src) => new RegExp(src, 'gi'));
found = 0;
if (CLAIM_PATTERNS.length) {
  for (const f of [...walkContent('src/content'), ...walkContent('src/pages'), ...walkContent('src/layouts'), ...walkContent('src/components'), 'src/data/facts.json']) {
    const text = readFileSync(f, 'utf8');
    for (const re of CLAIM_PATTERNS) {
      for (const m of text.matchAll(re)) {
        const line = text.slice(0, m.index).split('\n').length;
        bad(`${f}:${line} says "${m[0]}" — a claim the site may not make (voice.json → site.bannedClaims); state the figure flat and unattributed`);
        found = 1;
      }
    }
  }
}
if (!found) console.log(CLAIM_PATTERNS.length ? '   ok' : '   ok (no patterns configured — fill voice.json → site.bannedClaims)');

console.log('→ an inline `bars` figure cites one of the entry’s own sources (AGENTS § Figures)');
// A `bars` figure states numbers. It may take them from facts.json (`fact:`,
// resolved and verified at build time) or inline (`items:`), and an inline
// figure must name a `source` that is one of the entry's `sources` labels —
// otherwise a chart carries a figure the page never cites (AGENTS rule 1
// failing in a picture instead of a sentence).
found = 0;
for (const p of walkContent('src/content')) {
  const text = readFileSync(p, 'utf8');
  const fm = text.match(/^---\n([\s\S]*?)\n---/)?.[1] ?? '';
  if (!/^figures:/m.test(fm)) continue;
  const sourceLabels = [...fm.matchAll(/^\s+- label:\s*"((?:[^"\\]|\\.)*)"\s*$/gm)].map((m) => m[1]);
  const blocks = fm.split(/\n(?=  - kind:)/).filter((b) => /^\s*- kind:\s*"?bars"?/m.test(b));
  for (const b of blocks) {
    if (!/^\s+items:/m.test(b)) continue;
    const source = b.match(/^\s+source:\s*"((?:[^"\\]|\\.)*)"\s*$/m)?.[1];
    if (!source) {
      bad(`${p}: an inline bars figure has items but no source`);
      found = 1;
    } else if (!sourceLabels.includes(source)) {
      bad(`${p}: bars figure source "${source.slice(0, 60)}…" is not one of the entry's sources labels`);
      found = 1;
    }
  }
}
if (!found) console.log('   ok');

console.log('→ frontmatter titles survive the SERP clamp without a mid-phrase cut');
// BaseLayout runs every title through src/lib/clampTitle.ts, which clamps to
// 60 characters for the SERP. It sacrifices in order: a trailing " — clause",
// then a trailing " | clause", then a HARD CUT at the last word boundary. The
// first two are deliberate and read fine. The third is the defect: the
// ancestor site shipped 62–63 character titles and Google was served the
// promise cut off mid-phrase, on the one line a searcher reads. Nothing in the
// repo showed it, because the MDX carries the full string — and the built
// <title> ≤60 invariant passes precisely because the clamp did its job.
//
// So: a title is fine at 60 characters or fewer, or if it carries an em-dash or
// pipe clause that starts inside the budget (the clamp drops it whole).
// Anything else would be hard-cut, and fails here rather than in the SERP.
const CLAMP_MAX = 60; // keep in step with clampTitle's `max` default
found = 0;
for (const f of walkContent('src/content')) {
  if (!/\.mdx?$/.test(f)) continue;
  const text = readFileSync(f, 'utf8');
  if (/^draft:\s*true$/m.test(text)) continue;
  // Measure the VALUE, not the YAML: a single-quoted scalar doubles its
  // apostrophes ('' → '), a double-quoted one backslash-escapes.
  const tm = text.match(/^title:\s*(['"])(.+)\1\s*$/m);
  const title = tm ? (tm[1] === "'" ? tm[2].replace(/''/g, "'") : tm[2].replace(/\\(["\\])/g, '$1')) : null;
  if (!title || title.length <= CLAMP_MAX) continue;
  const emDash = title.lastIndexOf(' — ');
  const pipe = title.lastIndexOf(' | ');
  const clean = (emDash > 0 && emDash <= CLAMP_MAX) || (pipe > 0 && pipe <= CLAMP_MAX);
  if (!clean) {
    const cut = title.slice(0, CLAMP_MAX);
    bad(
      `${f} title is ${title.length} chars and would be hard-cut to "${cut.slice(0, cut.lastIndexOf(' '))}" — ` +
        `keep it to ${CLAMP_MAX}, or put the sacrificial half after " — " (src/lib/clampTitle.ts)`
    );
    found = 1;
  }
}
if (!found) console.log('   ok');

process.exit(fail);
